def response_from_dict(d: dict[str, Any], *, spider: Spider | None = None) -> Response:
    """Create a :class:`~scrapy.http.Response` object from a dict.

    If a spider is given, it will try to resolve the callbacks looking at the
    spider for methods with the same name.
    """
    from scrapy.http import HtmlResponse, Response, TextResponse
    from scrapy.utils.misc import load_object

    response_cls: type[Response] = load_object(d["_class"]) if "_class" in d else Response
    kwargs = {key: value for key, value in d.items() if key in response_cls.attributes}
    return response_cls(**kwargs)
